// Command unicodedata_go generates the UCD data files used by
// module/unicodedata from the headers that ship with CPython 3.14.
//
// Inputs:
//   - $CPYTHON/Modules/unicodedata_db.h: pre-generated by CPython's
//     own Tools/unicode/makeunicodedata.py from the Unicode 16.0
//     UCD source files. We re-parse the C output rather than the
//     UCD source so the runtime tables are byte-identical to
//     CPython.
//   - $CPYTHON/Objects/unicodetype_db.h: sister header that holds
//     the per-character type record (upper/lower/title deltas,
//     decimal digit, digit, flag bits) used by decimal / digit /
//     numeric (and isalpha / isdigit / islower / isupper /
//     istitle / ... once those land).
//
// Outputs:
//   - module/unicodedata/data_gen.go: arrays for unicodedata_db.h.
//   - module/unicodedata/type_gen.go: arrays for unicodetype_db.h
//     plus the parsed _PyUnicode_ToNumeric switch.
//
// Run with:
//
//	go run ./Tools/unicodedata_go \
//	  -cpython=$HOME/cpython-314 \
//	  -out=module/unicodedata/data_gen.go \
//	  -out-type=module/unicodedata/type_gen.go
//
// Both outputs are checked in. The runtime build has no Python
// dependency.
//
// CPython: Modules/unicodedata_db.h (generator output)
// CPython: Objects/unicodetype_db.h (generator output)
// CPython: Tools/unicode/makeunicodedata.py (generator)
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

func main() {
	cpython := flag.String("cpython", "", "path to cpython source tree")
	out := flag.String("out", "", "output Go file (unicodedata_db.h port)")
	outType := flag.String("out-type", "", "output Go file (unicodetype_db.h port)")
	outName := flag.String("out-name", "", "output Go file (unicodename_db.h port)")
	flag.Parse()
	if *cpython == "" || *out == "" {
		log.Fatal("both -cpython and -out required")
	}

	dbPath := filepath.Join(*cpython, "Modules", "unicodedata_db.h")
	src, err := os.ReadFile(dbPath)
	if err != nil {
		log.Fatal(err)
	}
	doc, err := parseDB(string(src))
	if err != nil {
		log.Fatal(err)
	}
	writeFormatted(*out, func(w *bytes.Buffer) error { return emit(w, doc) })

	if *outType != "" {
		typePath := filepath.Join(*cpython, "Objects", "unicodetype_db.h")
		ctypePath := filepath.Join(*cpython, "Objects", "unicodectype.c")
		typeSrc, err := os.ReadFile(typePath)
		if err != nil {
			log.Fatal(err)
		}
		ctypeSrc, err := os.ReadFile(ctypePath)
		if err != nil {
			log.Fatal(err)
		}
		tdoc, err := parseTypeDB(string(typeSrc), string(ctypeSrc))
		if err != nil {
			log.Fatal(err)
		}
		writeFormatted(*outType, func(w *bytes.Buffer) error { return emitType(w, tdoc) })
	}

	if *outName != "" {
		namePath := filepath.Join(*cpython, "Modules", "unicodename_db.h")
		udPath := filepath.Join(*cpython, "Modules", "unicodedata.c")
		nameSrc, err := os.ReadFile(namePath)
		if err != nil {
			log.Fatal(err)
		}
		udSrc, err := os.ReadFile(udPath)
		if err != nil {
			log.Fatal(err)
		}
		ndoc, err := parseNameDB(string(nameSrc), string(udSrc))
		if err != nil {
			log.Fatal(err)
		}
		writeFormatted(*outName, func(w *bytes.Buffer) error { return emitName(w, ndoc) })
	}
}

func writeFormatted(path string, fn func(*bytes.Buffer) error) {
	var buf bytes.Buffer
	if err := fn(&buf); err != nil {
		log.Fatal(err)
	}
	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		_ = os.WriteFile(path+".raw", buf.Bytes(), 0o644)
		log.Fatalf("gofmt %s: %v (raw dump at %s.raw)", path, err, path)
	}
	if err := os.WriteFile(path, formatted, 0o644); err != nil {
		log.Fatal(err)
	}
}

// db is the in-memory shape of the parts of unicodedata_db.h we
// care about. Each named array is a flat []uint32 (widening to fit
// the largest entry); the consumers cast back to the runtime type.
type db struct {
	version string
	shift   int
	decomp  int
	comp    int
	first   int
	last    int

	records       [][]uint32 // 6-tuples
	categoryNames []string
	bidiNames     []string
	eawNames      []string
	decompPrefix  []string
	index1        []uint32
	index2        []uint32
	decompData    []uint32
	decompIndex1  []uint32
	decompIndex2  []uint32
	compIndex     []uint32
	compData      []uint32
	nfcFirst      []reindex
	nfcLast       []reindex
}

type reindex struct {
	start, count, index int
}

func parseDB(src string) (*db, error) {
	out := &db{}

	if m := regexp.MustCompile(`#define UNIDATA_VERSION "([^"]+)"`).FindStringSubmatch(src); m != nil {
		out.version = m[1]
	}
	if v, ok := defineInt(src, "SHIFT"); ok {
		out.shift = v
	}
	if v, ok := defineInt(src, "DECOMP_SHIFT"); ok {
		out.decomp = v
	}
	if v, ok := defineInt(src, "COMP_SHIFT"); ok {
		out.comp = v
	}
	if v, ok := defineInt(src, "TOTAL_FIRST"); ok {
		out.first = v
	}
	if v, ok := defineInt(src, "TOTAL_LAST"); ok {
		out.last = v
	}

	// _PyUnicode_Database_Records is a list of {a, b, c, d, e, f}
	// tuples; parse with the tuple-walker because regexp on the
	// braces is ambiguous against the outer braces.
	recBody, err := extractBlock(src, "_PyUnicode_Database_Records[] = {")
	if err != nil {
		return nil, fmt.Errorf("records: %w", err)
	}
	out.records = parseTupleList(recBody, 6)

	// Name arrays.
	if out.categoryNames, err = extractStrings(src, "_PyUnicode_CategoryNames[] = {"); err != nil {
		return nil, fmt.Errorf("category names: %w", err)
	}
	if out.bidiNames, err = extractStrings(src, "_PyUnicode_BidirectionalNames[] = {"); err != nil {
		return nil, fmt.Errorf("bidirectional names: %w", err)
	}
	if out.eawNames, err = extractStrings(src, "_PyUnicode_EastAsianWidthNames[] = {"); err != nil {
		return nil, fmt.Errorf("east_asian_width names: %w", err)
	}
	if out.decompPrefix, err = extractStrings(src, "decomp_prefix[] = {"); err != nil {
		return nil, fmt.Errorf("decomp_prefix: %w", err)
	}

	// Flat integer arrays.
	for _, tab := range []struct {
		name string
		dst  *[]uint32
	}{
		{"index1[] = {", &out.index1},
		{"index2[] = {", &out.index2},
		{"decomp_data[] = {", &out.decompData},
		{"decomp_index1[] = {", &out.decompIndex1},
		{"decomp_index2[] = {", &out.decompIndex2},
		{"comp_index[] = {", &out.compIndex},
		// Leading space disambiguates from decomp_data[] = {.
		{" comp_data[] = {", &out.compData},
	} {
		body, err := extractBlock(src, tab.name)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", tab.name, err)
		}
		*tab.dst = parseInts(body)
	}

	// nfc_first / nfc_last are struct reindex tuples.
	if body, err := extractBlock(src, "nfc_first[] = {"); err == nil {
		out.nfcFirst = parseReindex(body)
	} else {
		return nil, fmt.Errorf("nfc_first: %w", err)
	}
	if body, err := extractBlock(src, "nfc_last[] = {"); err == nil {
		out.nfcLast = parseReindex(body)
	} else {
		return nil, fmt.Errorf("nfc_last: %w", err)
	}

	return out, nil
}

var defineRE = regexp.MustCompile(`(?m)^#define\s+([A-Z_]+)\s+(\d+)\s*$`)

func defineInt(src, name string) (int, bool) {
	for _, m := range defineRE.FindAllStringSubmatch(src, -1) {
		if m[1] == name {
			v, _ := strconv.Atoi(m[2])
			return v, true
		}
	}
	return 0, false
}

// extractBlock finds the substring between `start` and the next
// matching `};`, returning the inner text.
func extractBlock(src, start string) (string, error) {
	i := strings.Index(src, start)
	if i < 0 {
		return "", fmt.Errorf("not found: %s", start)
	}
	rest := src[i+len(start):]
	j := strings.Index(rest, "};")
	if j < 0 {
		return "", fmt.Errorf("unterminated: %s", start)
	}
	return rest[:j], nil
}

// extractStrings parses a `static const char *name[] = { "a", "b", NULL };`
// block (or similar) into a slice of Go strings, dropping the
// trailing NULL sentinel if present.
func extractStrings(src, start string) ([]string, error) {
	body, err := extractBlock(src, start)
	if err != nil {
		return nil, err
	}
	var out []string
	i := 0
	for i < len(body) {
		switch {
		case body[i] == '"':
			j := i + 1
			for j < len(body) && body[j] != '"' {
				if body[j] == '\\' {
					j++
				}
				j++
			}
			if j >= len(body) {
				return nil, fmt.Errorf("unterminated string at offset %d", i)
			}
			lit, err := strconv.Unquote(body[i : j+1])
			if err != nil {
				return nil, fmt.Errorf("unquote at %d: %w", i, err)
			}
			out = append(out, lit)
			i = j + 1
		case body[i] == 'N' && strings.HasPrefix(body[i:], "NULL"):
			i += 4
		default:
			i++
		}
	}
	return out, nil
}

// parseInts walks a comma-separated sequence of decimal / hex
// integers, ignoring whitespace and comments. Returns the flat
// []uint32.
func parseInts(body string) []uint32 {
	body = stripComments(body)
	var out []uint32
	i := 0
	for i < len(body) {
		c := body[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == ',' || c == '\r':
			i++
		case c == '0' && i+1 < len(body) && (body[i+1] == 'x' || body[i+1] == 'X'):
			j := i + 2
			for j < len(body) && isHex(body[j]) {
				j++
			}
			n, _ := strconv.ParseUint(body[i+2:j], 16, 64)
			out = append(out, uint32(n))
			i = j
		case c >= '0' && c <= '9':
			j := i
			for j < len(body) && body[j] >= '0' && body[j] <= '9' {
				j++
			}
			n, _ := strconv.ParseUint(body[i:j], 10, 64)
			out = append(out, uint32(n))
			i = j
		default:
			i++
		}
	}
	return out
}

// parseTupleList walks a `{a, b, ...}, {...}, ...` sequence and
// returns one []uint32 per tuple. Tuples must be `arity` wide.
func parseTupleList(body string, arity int) [][]uint32 {
	body = stripComments(body)
	var out [][]uint32
	i := 0
	for i < len(body) {
		c := body[i]
		switch {
		case c == '{':
			j := strings.IndexByte(body[i:], '}')
			if j < 0 {
				return out
			}
			tup := parseInts(body[i+1 : i+j])
			if len(tup) != arity {
				log.Fatalf("tuple arity mismatch: got %d, want %d in %q", len(tup), arity, body[i:i+j+1])
			}
			out = append(out, tup)
			i += j + 1
		default:
			i++
		}
	}
	return out
}

// parseReindex walks a sequence of `{start, count, index}` triples.
func parseReindex(body string) []reindex {
	tuples := parseTupleList(body, 3)
	out := make([]reindex, len(tuples))
	for i, t := range tuples {
		out[i] = reindex{int(t[0]), int(t[1]), int(t[2])}
	}
	return out
}

func stripComments(s string) string {
	for {
		i := strings.Index(s, "/*")
		if i < 0 {
			return s
		}
		j := strings.Index(s[i:], "*/")
		if j < 0 {
			return s[:i]
		}
		s = s[:i] + s[i+j+2:]
	}
}

func isHex(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func emit(w *bytes.Buffer, d *db) error {
	fmt.Fprint(w, `// Code generated by Tools/unicodedata_go. DO NOT EDIT.
//
// Source: $CPYTHON/Modules/unicodedata_db.h
//
// CPython: Modules/unicodedata_db.h
// CPython: Tools/unicode/makeunicodedata.py

package unicodedata

`)
	fmt.Fprintf(w, "const unidataVersion = %q\n\n", d.version)
	fmt.Fprintf(w, "const recShift = %d\n", d.shift)
	fmt.Fprintf(w, "const decompShift = %d\n", d.decomp)
	fmt.Fprintf(w, "const compShift = %d\n", d.comp)
	fmt.Fprintf(w, "const totalFirst = %d\n", d.first)
	fmt.Fprintf(w, "const totalLast = %d\n\n", d.last)

	emitStrings(w, "categoryNames", d.categoryNames)
	emitStrings(w, "bidirectionalNames", d.bidiNames)
	emitStrings(w, "eastAsianWidthNames", d.eawNames)
	emitStrings(w, "decompPrefix", d.decompPrefix)

	// dbRecord 6-tuple: {category, combining, bidirectional,
	// mirrored, east_asian_width, normalization_quick_check}.
	fmt.Fprint(w, "type dbRecord struct{ Category, Combining, Bidirectional, Mirrored, EastAsianWidth, NormalizationQC uint8 }\n\n")
	fmt.Fprintf(w, "var dbRecords = [%d]dbRecord{\n", len(d.records))
	for _, r := range d.records {
		fmt.Fprintf(w, "{%d, %d, %d, %d, %d, %d},\n", r[0], r[1], r[2], r[3], r[4], r[5])
	}
	fmt.Fprint(w, "}\n\n")

	emitUint16(w, "index1", d.index1)
	emitUint16(w, "index2", d.index2)
	emitUint32(w, "decompData", d.decompData)
	emitUint8(w, "decompIndex1", d.decompIndex1)
	emitUint16(w, "decompIndex2", d.decompIndex2)
	emitUint16(w, "compIndex", d.compIndex)
	emitUint32(w, "compData", d.compData)

	fmt.Fprint(w, "type reindexEntry struct{ Start, Count, Index int }\n\n")
	emitReindex(w, "nfcFirst", d.nfcFirst)
	emitReindex(w, "nfcLast", d.nfcLast)

	return nil
}

func emitStrings(w *bytes.Buffer, name string, ss []string) {
	fmt.Fprintf(w, "var %s = []string{\n", name)
	for _, s := range ss {
		fmt.Fprintf(w, "%q,\n", s)
	}
	fmt.Fprint(w, "}\n\n")
}

func emitUint8(w *bytes.Buffer, name string, xs []uint32) {
	fmt.Fprintf(w, "var %s = [...]uint8{\n", name)
	for i, x := range xs {
		fmt.Fprintf(w, "%d,", x)
		if i%32 == 31 {
			fmt.Fprintln(w)
		}
	}
	fmt.Fprint(w, "\n}\n\n")
}

func emitUint16(w *bytes.Buffer, name string, xs []uint32) {
	fmt.Fprintf(w, "var %s = [...]uint16{\n", name)
	for i, x := range xs {
		fmt.Fprintf(w, "%d,", x)
		if i%32 == 31 {
			fmt.Fprintln(w)
		}
	}
	fmt.Fprint(w, "\n}\n\n")
}

func emitUint32(w *bytes.Buffer, name string, xs []uint32) {
	fmt.Fprintf(w, "var %s = [...]uint32{\n", name)
	for i, x := range xs {
		fmt.Fprintf(w, "%d,", x)
		if i%16 == 15 {
			fmt.Fprintln(w)
		}
	}
	fmt.Fprint(w, "\n}\n\n")
}

func emitReindex(w *bytes.Buffer, name string, rs []reindex) {
	fmt.Fprintf(w, "var %s = []reindexEntry{\n", name)
	for _, r := range rs {
		fmt.Fprintf(w, "{%d, %d, %d},\n", r.start, r.count, r.index)
	}
	fmt.Fprint(w, "}\n\n")
}

// typeDB is the in-memory shape of unicodetype_db.h + the parsed
// _PyUnicode_ToNumeric switch from unicodectype.c. Mirrors the C
// _PyUnicode_TypeRecord layout: upper/lower/title are signed deltas
// (or offsets into an extended-case table when the EXTENDED_CASE
// flag bit is set), decimal/digit are unsigned char, flags is the
// bitfield CPython uses for isalpha/isdigit/islower/...
type typeDB struct {
	shift   int
	records [][6]int64 // {upper, lower, title, decimal, digit, flags}
	index1  []uint32
	index2  []uint32
	numeric []numericEntry
}

type numericEntry struct {
	code  rune
	value float64
}

// parseTypeDB walks unicodetype_db.h for the type record table plus
// the two index arrays, then walks unicodectype.c for the
// _PyUnicode_ToNumeric switch (one entry per `case 0xXXXX:`).
//
// CPython: Objects/unicodetype_db.h (records + index1/index2)
// CPython: Objects/unicodetype_db.h:4513 _PyUnicode_ToNumeric
func parseTypeDB(src, ctype string) (*typeDB, error) {
	out := &typeDB{}
	if v, ok := defineInt(src, "SHIFT"); ok {
		out.shift = v
	} else {
		return nil, fmt.Errorf("SHIFT not defined in unicodetype_db.h")
	}

	body, err := extractBlock(src, "_PyUnicode_TypeRecords[] = {")
	if err != nil {
		return nil, fmt.Errorf("type records: %w", err)
	}
	out.records = parseSignedTupleList(body, 6)

	for _, tab := range []struct {
		name string
		dst  *[]uint32
	}{
		{"index1[] = {", &out.index1},
		{"index2[] = {", &out.index2},
	} {
		b, err := extractBlock(src, tab.name)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", tab.name, err)
		}
		*tab.dst = parseInts(b)
	}

	// Walk unicodectype.c for the _PyUnicode_ToNumeric switch.
	out.numeric, err = parseNumericSwitch(src, ctype)
	if err != nil {
		return nil, fmt.Errorf("numeric switch: %w", err)
	}
	return out, nil
}

// parseSignedTupleList walks `{a, b, c, d, e, f}, ...` allowing
// negative leading signs (upper/lower/title can be negative).
func parseSignedTupleList(body string, arity int) [][6]int64 {
	body = stripComments(body)
	var out [][6]int64
	i := 0
	for i < len(body) {
		if body[i] != '{' {
			i++
			continue
		}
		j := strings.IndexByte(body[i:], '}')
		if j < 0 {
			return out
		}
		tup := parseSignedInts(body[i+1 : i+j])
		if len(tup) != arity {
			log.Fatalf("type-record arity: got %d want %d in %q", len(tup), arity, body[i:i+j+1])
		}
		var row [6]int64
		copy(row[:], tup)
		out = append(out, row)
		i += j + 1
	}
	return out
}

func parseSignedInts(body string) []int64 {
	body = stripComments(body)
	var out []int64
	i := 0
	for i < len(body) {
		c := body[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ',':
			i++
		case c == '-' || (c >= '0' && c <= '9'):
			j := i
			if c == '-' {
				j++
			}
			if j+1 < len(body) && body[j] == '0' && (body[j+1] == 'x' || body[j+1] == 'X') {
				k := j + 2
				for k < len(body) && isHex(body[k]) {
					k++
				}
				n, _ := strconv.ParseInt(body[j+2:k], 16, 64)
				if c == '-' {
					n = -n
				}
				out = append(out, n)
				i = k
				continue
			}
			for j < len(body) && body[j] >= '0' && body[j] <= '9' {
				j++
			}
			n, _ := strconv.ParseInt(body[i:j], 10, 64)
			out = append(out, n)
			i = j
		default:
			i++
		}
	}
	return out
}

// parseNumericSwitch walks the `_PyUnicode_ToNumeric` switch and
// returns one numericEntry per `case 0xNNNN:` cluster. Each cluster
// of consecutive `case` labels shares the next `return (double)
// LITERAL;` payload, which we evaluate as either a single number or
// an `a/b` ratio (the C source uses both forms).
//
// The switch lives at Objects/unicodetype_db.h:4513; we re-read the
// header text because the entire function body is in that file (the
// `unicodectype.c` argument is reserved for future use but we keep
// the signature flexible so the caller can pass the .c file when the
// switch moves there).
//
// CPython: Objects/unicodetype_db.h:4513 _PyUnicode_ToNumeric
func parseNumericSwitch(src, _ string) ([]numericEntry, error) {
	start := strings.Index(src, "_PyUnicode_ToNumeric")
	if start < 0 {
		return nil, fmt.Errorf("_PyUnicode_ToNumeric not found")
	}
	body := src[start:]
	end := strings.Index(body, "\n}\n")
	if end < 0 {
		return nil, fmt.Errorf("_PyUnicode_ToNumeric: end brace not found")
	}
	body = body[:end]

	caseRE := regexp.MustCompile(`(?m)^\s*case\s+0x([0-9A-Fa-f]+)\s*:`)
	retRE := regexp.MustCompile(`(?m)^\s*return\s+\(double\)\s*([^;]+);`)

	type tok struct {
		pos  int
		kind byte // 'c' = case, 'r' = return
		text string
	}
	var toks []tok
	for _, m := range caseRE.FindAllStringSubmatchIndex(body, -1) {
		toks = append(toks, tok{pos: m[0], kind: 'c', text: body[m[2]:m[3]]})
	}
	for _, m := range retRE.FindAllStringSubmatchIndex(body, -1) {
		toks = append(toks, tok{pos: m[0], kind: 'r', text: strings.TrimSpace(body[m[2]:m[3]])})
	}
	if len(toks) == 0 {
		return nil, fmt.Errorf("no cases parsed")
	}
	// Sort by position.
	for i := 1; i < len(toks); i++ {
		for j := i; j > 0 && toks[j-1].pos > toks[j].pos; j-- {
			toks[j-1], toks[j] = toks[j], toks[j-1]
		}
	}

	var out []numericEntry
	pending := []rune{}
	for _, t := range toks {
		if t.kind == 'c' {
			n, err := strconv.ParseInt(t.text, 16, 32)
			if err != nil {
				return nil, fmt.Errorf("bad case hex %q: %w", t.text, err)
			}
			pending = append(pending, rune(n))
			continue
		}
		val, err := evalNumeric(t.text)
		if err != nil {
			return nil, fmt.Errorf("numeric expr %q: %w", t.text, err)
		}
		for _, code := range pending {
			out = append(out, numericEntry{code: code, value: val})
		}
		pending = pending[:0]
	}
	return out, nil
}

// evalNumeric reads `a` or `a/b` (with optional unary `-`), matching
// the C literals CPython's makeunicodedata.py emits.
func evalNumeric(expr string) (float64, error) {
	expr = strings.TrimSpace(expr)
	// Strip a leading "(double) " cast if any leaked through.
	expr = strings.TrimPrefix(expr, "(double)")
	expr = strings.TrimSpace(expr)
	if i := strings.Index(expr, "/"); i >= 0 {
		num, err1 := strconv.ParseFloat(strings.TrimSpace(expr[:i]), 64)
		den, err2 := strconv.ParseFloat(strings.TrimSpace(expr[i+1:]), 64)
		if err1 != nil || err2 != nil {
			return 0, fmt.Errorf("ratio parse: %s", expr)
		}
		return num / den, nil
	}
	return strconv.ParseFloat(expr, 64)
}

// emitType writes module/unicodedata/type_gen.go.
//
// CPython: Objects/unicodetype_db.h (data)
// CPython: Objects/unicodectype.c:43 gettyperecord
func emitType(w *bytes.Buffer, d *typeDB) error {
	fmt.Fprint(w, `// Code generated by Tools/unicodedata_go. DO NOT EDIT.
//
// Source: $CPYTHON/Objects/unicodetype_db.h
// Source: $CPYTHON/Objects/unicodectype.c (_PyUnicode_ToNumeric switch)
//
// CPython: Objects/unicodetype_db.h
// CPython: Objects/unicodectype.c

package unicodedata

`)
	fmt.Fprintf(w, "const typeShift = %d\n\n", d.shift)
	fmt.Fprint(w, "// typeRecord mirrors _PyUnicode_TypeRecord.\n")
	fmt.Fprint(w, "// CPython: Objects/unicodectype.c:27 _PyUnicode_TypeRecord\n")
	fmt.Fprint(w, "type typeRecord struct{ Upper, Lower, Title int32; Decimal, Digit uint8; Flags uint16 }\n\n")
	fmt.Fprintf(w, "var typeRecords = [%d]typeRecord{\n", len(d.records))
	for _, r := range d.records {
		fmt.Fprintf(w, "{%d, %d, %d, %d, %d, %d},\n", r[0], r[1], r[2], r[3], r[4], r[5])
	}
	fmt.Fprint(w, "}\n\n")

	emitUint16(w, "typeIndex1", d.index1)
	emitUint16(w, "typeIndex2", d.index2)

	fmt.Fprint(w, "// numericValues maps each codepoint with a numeric value to its\n")
	fmt.Fprint(w, "// double, exactly as _PyUnicode_ToNumeric does. CPython compiles a\n")
	fmt.Fprint(w, "// dense switch; the Go port keeps it as a map for lookup symmetry.\n")
	fmt.Fprint(w, "// CPython: Objects/unicodetype_db.h:4513 _PyUnicode_ToNumeric\n")
	fmt.Fprintf(w, "var numericValues = map[rune]float64{\n")
	for _, e := range d.numeric {
		fmt.Fprintf(w, "0x%04X: %s,\n", e.code, formatFloat(e.value))
	}
	fmt.Fprint(w, "}\n\n")
	return nil
}

func formatFloat(v float64) string {
	if v == float64(int64(v)) {
		return strconv.FormatFloat(v, 'f', 1, 64)
	}
	return strconv.FormatFloat(v, 'g', -1, 64)
}

// nameDB is the parsed shape of unicodename_db.h plus the
// hangul_syllables[][3] table from unicodedata.c. The DAWG is left
// as the raw byte stream CPython emits; the runtime walks it via
// the same varint protocol.
type nameDB struct {
	posShift        int
	posNotFound     uint32
	aliasesStart    uint32
	aliasesEnd      uint32
	namedSeqStart   uint32
	namedSeqEnd     uint32
	packed          []byte
	posToCode       []uint32
	codeToPosIndex1 []uint32
	codeToPosIndex2 []uint32
	aliases         []uint32
	namedSequences  []namedSeq
	derivedRanges   []derivedRange
	derivedPrefixes []string
	hangulSyllables [][3]string
}

type namedSeq struct {
	seq []uint16
}

type derivedRange struct {
	first    uint32
	last     uint32
	prefixID int
}

// parseNameDB walks unicodename_db.h (DAWG + index tables + aliases
// + named sequences + derived-name ranges + derived-name prefixes)
// and unicodedata.c (hangul_syllables[][3]).
//
// CPython: Modules/unicodename_db.h (generator output)
// CPython: Modules/unicodedata.c:1004 hangul_syllables
func parseNameDB(src, udSrc string) (*nameDB, error) {
	out := &nameDB{}
	if v, ok := defineInt(src, "DAWG_CODEPOINT_TO_POS_SHIFT"); ok {
		out.posShift = v
	} else {
		return nil, fmt.Errorf("DAWG_CODEPOINT_TO_POS_SHIFT not defined")
	}
	if v, ok := defineInt(src, "DAWG_CODEPOINT_TO_POS_NOTFOUND"); ok {
		out.posNotFound = uint32(v)
	} else {
		return nil, fmt.Errorf("DAWG_CODEPOINT_TO_POS_NOTFOUND not defined")
	}
	if v, ok := staticConstUint(src, "aliases_start"); ok {
		out.aliasesStart = v
	}
	if v, ok := staticConstUint(src, "aliases_end"); ok {
		out.aliasesEnd = v
	}
	if v, ok := staticConstUint(src, "named_sequences_start"); ok {
		out.namedSeqStart = v
	}
	if v, ok := staticConstUint(src, "named_sequences_end"); ok {
		out.namedSeqEnd = v
	}

	if body, err := extractBlock(src, "packed_name_dawg[] = {"); err == nil {
		ints := parseInts(body)
		out.packed = make([]byte, len(ints))
		for i, v := range ints {
			out.packed[i] = byte(v)
		}
	} else {
		return nil, err
	}
	if body, err := extractBlock(src, "dawg_pos_to_codepoint[] = {"); err == nil {
		out.posToCode = parseInts(body)
	} else {
		return nil, err
	}
	if body, err := extractBlock(src, "dawg_codepoint_to_pos_index1[] = {"); err == nil {
		out.codeToPosIndex1 = parseInts(body)
	} else {
		return nil, err
	}
	if body, err := extractBlock(src, "dawg_codepoint_to_pos_index2[] = {"); err == nil {
		out.codeToPosIndex2 = parseInts(body)
	} else {
		return nil, err
	}
	if body, err := extractBlock(src, "name_aliases[] = {"); err == nil {
		out.aliases = parseInts(body)
	} else {
		return nil, err
	}

	if body, err := extractBlock(src, "named_sequences[] = {"); err == nil {
		out.namedSequences = parseNamedSequences(body)
	} else {
		return nil, err
	}

	if body, err := extractBlock(src, "derived_name_ranges[] = {"); err == nil {
		out.derivedRanges = parseDerivedRanges(body)
	} else {
		return nil, err
	}

	if body, err := extractBlock(src, "derived_name_prefixes[] = {"); err == nil {
		out.derivedPrefixes = parseDerivedPrefixes(body)
	} else {
		return nil, err
	}

	hang, err := parseHangulSyllables(udSrc)
	if err != nil {
		return nil, err
	}
	out.hangulSyllables = hang
	return out, nil
}

// staticConstUint pulls the integer literal out of a
// `static const unsigned int NAME = VALUE;` line.
func staticConstUint(src, name string) (uint32, bool) {
	re := regexp.MustCompile(`static const unsigned int ` + regexp.QuoteMeta(name) + `\s*=\s*(0x[0-9a-fA-F]+|\d+)\s*;`)
	if m := re.FindStringSubmatch(src); m != nil {
		base := 10
		s := m[1]
		if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
			base = 16
			s = s[2:]
		}
		v, err := strconv.ParseUint(s, base, 64)
		if err == nil {
			return uint32(v), true
		}
	}
	return 0, false
}

// parseNamedSequences walks a `{n, {a,b,c,d}}, ...` list. Each entry
// has a leading length then a Py_UCS2 array of fixed size 4; only
// the first `seqlen` items are meaningful.
func parseNamedSequences(body string) []namedSeq {
	body = stripComments(body)
	var out []namedSeq
	i := 0
	for i < len(body) {
		if body[i] != '{' {
			i++
			continue
		}
		// outer brace
		j := i + 1
		// find matching closing brace at depth 0
		depth := 1
		for j < len(body) && depth > 0 {
			switch body[j] {
			case '{':
				depth++
			case '}':
				depth--
			}
			j++
		}
		if depth != 0 {
			return out
		}
		inner := body[i+1 : j-1]
		// inner has format: SEQLEN, {U+0023, U+FE0F, ...}
		commaIdx := strings.IndexByte(inner, ',')
		if commaIdx < 0 {
			i = j
			continue
		}
		seqlenStr := strings.TrimSpace(inner[:commaIdx])
		seqlen, _ := strconv.Atoi(seqlenStr)
		braceStart := strings.IndexByte(inner[commaIdx:], '{')
		if braceStart < 0 {
			i = j
			continue
		}
		braceStart += commaIdx
		braceEnd := strings.IndexByte(inner[braceStart:], '}')
		if braceEnd < 0 {
			i = j
			continue
		}
		braceEnd += braceStart
		nums := parseInts(inner[braceStart+1 : braceEnd])
		if len(nums) < seqlen {
			seqlen = len(nums)
		}
		seq := make([]uint16, seqlen)
		for k := 0; k < seqlen; k++ {
			seq[k] = uint16(nums[k])
		}
		out = append(out, namedSeq{seq: seq})
		i = j
	}
	return out
}

// parseDerivedRanges walks `{first, last, prefixid}` triples.
func parseDerivedRanges(body string) []derivedRange {
	tuples := parseTupleList(body, 3)
	out := make([]derivedRange, len(tuples))
	for i, t := range tuples {
		out[i] = derivedRange{first: t[0], last: t[1], prefixID: int(t[2])}
	}
	return out
}

// parseDerivedPrefixes parses the trailing string-list:
// `static const char * const derived_name_prefixes[] = {"X","Y",...};`.
func parseDerivedPrefixes(body string) []string {
	var out []string
	i := 0
	for i < len(body) {
		if body[i] != '"' {
			i++
			continue
		}
		j := i + 1
		for j < len(body) && body[j] != '"' {
			if body[j] == '\\' {
				j++
			}
			j++
		}
		if j >= len(body) {
			break
		}
		lit, err := strconv.Unquote(body[i : j+1])
		if err == nil {
			out = append(out, lit)
		}
		i = j + 1
	}
	return out
}

// parseHangulSyllables pulls the {{"G","A",""},...} table out of
// unicodedata.c.
//
// CPython: Modules/unicodedata.c:1004 hangul_syllables
func parseHangulSyllables(src string) ([][3]string, error) {
	body, err := extractBlock(src, "hangul_syllables[][3] = {")
	if err != nil {
		return nil, err
	}
	var out [][3]string
	i := 0
	for i < len(body) {
		if body[i] != '{' {
			i++
			continue
		}
		j := strings.IndexByte(body[i:], '}')
		if j < 0 {
			break
		}
		row := body[i+1 : i+j]
		cells := parseHangulRow(row)
		if len(cells) == 3 {
			out = append(out, [3]string{cells[0], cells[1], cells[2]})
		}
		i += j + 1
	}
	return out, nil
}

// parseHangulRow turns `"G", "A", ""` (or `0, "AE", "G"`) into a
// 3-string slice. A bare `0` becomes the empty string.
func parseHangulRow(row string) []string {
	var out []string
	i := 0
	for i < len(row) {
		c := row[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == ',':
			i++
		case c == '"':
			j := i + 1
			for j < len(row) && row[j] != '"' {
				if row[j] == '\\' {
					j++
				}
				j++
			}
			if j >= len(row) {
				return out
			}
			lit, err := strconv.Unquote(row[i : j+1])
			if err == nil {
				out = append(out, lit)
			}
			i = j + 1
		case c == '0':
			out = append(out, "")
			i++
		default:
			i++
		}
	}
	return out
}

func emitName(w *bytes.Buffer, d *nameDB) error {
	fmt.Fprint(w, `// Code generated by Tools/unicodedata_go. DO NOT EDIT.
//
// Source: $CPYTHON/Modules/unicodename_db.h
// Source: $CPYTHON/Modules/unicodedata.c (hangul_syllables table)
//
// CPython: Modules/unicodename_db.h
// CPython: Modules/unicodedata.c:1004 hangul_syllables

package unicodedata

`)
	fmt.Fprintf(w, "const dawgPosShift = %d\n", d.posShift)
	fmt.Fprintf(w, "const dawgPosNotFound = %d\n", d.posNotFound)
	fmt.Fprintf(w, "const aliasesStart = 0x%X\n", d.aliasesStart)
	fmt.Fprintf(w, "const aliasesEnd = 0x%X\n", d.aliasesEnd)
	fmt.Fprintf(w, "const namedSeqStart = 0x%X\n", d.namedSeqStart)
	fmt.Fprintf(w, "const namedSeqEnd = 0x%X\n\n", d.namedSeqEnd)

	fmt.Fprintf(w, "var packedNameDawg = [...]byte{\n")
	for i, b := range d.packed {
		fmt.Fprintf(w, "%d,", b)
		if i%32 == 31 {
			fmt.Fprintln(w)
		}
	}
	fmt.Fprint(w, "\n}\n\n")

	emitUint32(w, "dawgPosToCode", d.posToCode)
	emitUint8(w, "dawgCodeToPosIndex1", d.codeToPosIndex1)
	emitUint16(w, "dawgCodeToPosIndex2", d.codeToPosIndex2)
	emitUint32(w, "nameAliases", d.aliases)

	fmt.Fprint(w, "type namedSequence struct{ Seq []uint16 }\n\n")
	fmt.Fprintf(w, "var namedSequences = []namedSequence{\n")
	for _, ns := range d.namedSequences {
		fmt.Fprint(w, "{Seq: []uint16{")
		for i, c := range ns.seq {
			if i > 0 {
				fmt.Fprint(w, ", ")
			}
			fmt.Fprintf(w, "0x%X", c)
		}
		fmt.Fprint(w, "}},\n")
	}
	fmt.Fprint(w, "}\n\n")

	fmt.Fprint(w, "type derivedNameRange struct{ First, Last rune; PrefixID int }\n\n")
	fmt.Fprintf(w, "var derivedNameRanges = []derivedNameRange{\n")
	for _, r := range d.derivedRanges {
		fmt.Fprintf(w, "{First: 0x%X, Last: 0x%X, PrefixID: %d},\n", r.first, r.last, r.prefixID)
	}
	fmt.Fprint(w, "}\n\n")

	emitStrings(w, "derivedNamePrefixes", d.derivedPrefixes)

	fmt.Fprintf(w, "var hangulSyllables = [...][3]string{\n")
	for _, row := range d.hangulSyllables {
		fmt.Fprintf(w, "{%q, %q, %q},\n", row[0], row[1], row[2])
	}
	fmt.Fprint(w, "}\n\n")
	return nil
}
